import {lessons,recipes,workflows,commands,sources} from '../content.js?v=0.5.0';
import {e,sourceLink,command,breadcrumb,pageHead,lessonCard,problemCard,workflowCard,notFound} from '../ui.js?v=0.5.0';
export function home({completed=[]}={}){
 const common=['state-locked','unexpected-destroy','provider-download','partial-apply','authentication','already-exists'].map(id=>recipes.find(x=>x.id===id));
 return `<section class="hero"><div><div class="eyebrow"><span class="pill">A PRACTICAL TERRAFORM COMPANION</span></div><h1 id="page-heading">A clearer plan.<br>A calmer <em>next step.</em></h1><p>Get to grips with Terraform, understand what’s changing, and work through the errors that get in your way.</p><div class="hero-actions"><a class="button primary" href="#learn">Learn Terraform <span aria-hidden="true">→</span></a><a class="button secondary" href="#fix">Fix a problem <span aria-hidden="true">↗</span></a></div><div class="tiny-note">Free to explore. No accounts, cloud access or setup required.</div></div><div class="hero-demo" aria-label="Illustrative Terraform plan"><div class="window-head"><i></i><i></i><i></i><span>understand-the-plan.tf</span><span style="margin-left:auto">SIMULATED EXAMPLE</span></div><div class="demo-body"><div class="demo-caption">SMALL CHANGES. CLEAR CONSEQUENCES.</div><div class="demo-resource"><span class="code-comment"># terraform_data.message will be updated</span><br><span class="code-change">~</span> resource "terraform_data" "message" {<br>&nbsp;&nbsp;<span class="code-change">~</span> input = "Hello" <span class="code-add">→ "Hello again"</span><br>}</div><div class="plan-summary"><span class="code-add">+ 0 to add</span><span class="code-change">~ 1 to change</span><span class="muted">− 0 to destroy</span></div><div class="demo-note"><span aria-hidden="true">ⓘ</span><span>A plan proposes changes. You decide what happens next.</span></div></div></div></section>
 <button class="search-banner" data-open-search><span class="search-icon" aria-hidden="true">⌕</span><span>Search a task, command or error…</span><span class="key">Ctrl K</span></button>
 <section class="section" aria-labelledby="common-heading"><div class="section-heading"><div><h2 id="common-heading">Something not going to plan?</h2><p>Start with what you’re seeing. We’ll help you find your next check.</p></div><a class="text-link" href="#fix">All problems →</a></div><div class="problem-grid">${common.map(problemCard).join('')}</div></section>
 <section class="learning-banner"><div><div class="eyebrow">MAKE IT CLICK</div><h2>Four ideas. One useful mental model.</h2><p>What you want, what Terraform records, what actually exists, and what it proposes. See how they fit together.</p><a class="text-link" href="#lesson/mental-model">Explore the visual model →</a></div><div class="mini-model"><div class="mini-node">01 · Configuration<small>The result you describe</small></div><div class="mini-node">02 · State<small>The object bindings it records</small></div><div class="mini-node">03 · Infrastructure<small>What actually exists now</small></div><div class="mini-node">04 · Plan<small>The changes it proposes</small></div></div></section>
 <section class="section"><div class="section-heading"><div><h2>Build understanding, one step at a time.</h2><p>Short lessons with examples you can actually follow.</p></div><a class="text-link" href="#learn">Learning path →</a></div><div class="cards">${lessons.slice(0,3).map(l=>lessonCard(l,completed)).join('')}</div></section>
 <section class="section"><div class="section-heading"><div><h2>A little guidance for everyday work.</h2><p>Practical workflows, from your first project to a reviewed change.</p></div><a class="text-link" href="#workflows">All workflows →</a></div><div class="cards">${workflows.slice(0,3).map(workflowCard).join('')}</div></section>`;
}

export function reference(){return pageHead('REFERENCE / KEEP IT HANDY','The command is only half the story.','Look up a command, understand its effect, and follow its official documentation for the version you use.')+`<div class="table-wrap"><table><thead><tr><th>Command</th><th>Purpose</th><th>Effect / limit</th><th>Source</th></tr></thead><tbody>${commands.map(c=>`<tr><td><code>${e(c.name)}</code></td><td>${e(c.purpose)}</td><td>${e(c.effect)}</td><td>${sourceLink(c.source)}</td></tr>`).join('')}</tbody></table></div><div class="callout warning"><strong>No universal undo command</strong><p>State bindings, configuration history and backups of actual data solve different problems. Understand which one you need before attempting recovery.</p></div><section class="section"><h2>Plan symbols, in plain English</h2><div class="cards">${[['+','Create','Proposes a new managed instance.'],['~','Update','Proposes changing an instance in place. Operational impact can still be significant.'],['−','Delete','Proposes removing a managed instance. Check its data and dependencies.'],['−/+ or +/−','Replace','Proposes deleting and creating an instance. Read the actual ordering and reason.']].map(([symbol,title,text])=>`<div class="card"><span class="card-number">${symbol}</span><h3>${title}</h3><p>${text}</p></div>`).join('')}</div></section><section class="section"><h2>Official sources</h2><p class="small">Reviewed 16 October 2026. Check the documentation version selector and your provider’s versioned documentation. Guidance is not a compatibility certification.</p><div class="problem-grid">${Object.entries(sources).map(([key,url])=>`<a class="problem-card" target="_blank" rel="noopener noreferrer" href="${url}"><div><h3>${e(key.charAt(0).toUpperCase()+key.slice(1))}</h3><p>HashiCorp Developer documentation ↗</p></div></a>`).join('')}</div></section>`;}

export function about(){return pageHead('ABOUT / A PRACTICAL COMPANION','A clearer route through Terraform.','Terraform Unstuck is an independent visual learning and troubleshooting project inspired by GitUnstuck.')+`<article class="article"><h2>What this early version includes</h2><p>Eight lessons with practical tasks and understanding checks, guided troubleshooting questions, ${recipes.length} recipes, ${workflows.length} workflows, a plan simulator, global search and 13 ranked error-matching rules. Guided mode keeps explanations focused; Advanced adds optional context.</p><h2>Your input stays in this tab</h2><p>The error analyser uses local pattern matching. It does not send pasted input to a server, put it in share links, save it in browser storage, or use an AI service. Clear removes the draft and diagnosis. Navigating within this guide keeps the draft in memory until the page is reloaded or closed.</p><p>GitHub Pages serves the public website assets. External documentation links open the linked service when selected. This application contains no analytics, third-party fonts or remote scripts.</p><h2>What is saved locally</h2><p>Your theme, explanation mode and explicitly marked lesson progress are stored in this browser. Practice answers and troubleshooting selections stay in tab memory. They are optional convenience preferences.</p><button id="reset-preferences">Reset saved preferences and progress</button><h2>What this guide cannot know</h2><p>It cannot inspect your accounts, state, configuration or infrastructure. A pattern match is a pointer to guidance, not a confirmed root cause. The simulator uses fictional provider behaviour and does not execute Terraform. Examples have not been tested against live cloud accounts.</p><h2>About the project</h2><p>Built as an early implementation of the Terraform Unstuck plan. Visual conventions draw inspiration from <a href="https://github.com/dazzo31/gitunstuck" target="_blank" rel="noopener noreferrer">GitUnstuck</a>; this implementation uses new source and independent branding.</p><p>Terraform is a HashiCorp product. This project is not affiliated with HashiCorp or IBM.</p></article>`;}
